{"pageId": "dd862f1e-bac5-42be-8512-b078cb0fb8a2", "code": "return page.evaluate(() => {
  const frame = document.querySelector(".canvas-rce-page__frame");
  const chain = [];
  let el = frame;
  while (el && el !== document.documentElement) {
    const r = el.getBoundingClientRect();
    chain.push({ tag: el.tagName, cls: el.className, h: Math.round(r.height), top: Math.round(r.top) });
    el = el.parentElement;
  }
  return { innerHeight: window.innerHeight, navHeight: getComputedStyle(document.documentElement).getPropertyValue("--vp-nav-height"), chain };
});"}

